def keystone_auth_filter_factory(global_config, **local_config):
    global_config.update(local_config)
    config_file_name = global_config.get('config_file')
    if not config_file_name:
        raise ValueError("No config file specified")
    config_file = ConfigParser.SafeConfigParser()
    try:
        read_ok = config_file.read(config_file_name)
        if not read_ok:
            raise ValueError("Cannot open config file " + config_file_name)
        config_items = config_file.items('keystone_authtoken')
    except ConfigParser.NoSectionError:
        raise ValueError("Section [keystone_authtoken] not found in " + config_file_name)
    global_config.update(config_items)
    return auth_filter_factory(global_config)

