MAGIC = {
    'image/gif':     re.compile(r'^GIF'),
    'image/jpeg':    re.compile(r'^\xff\xd8\xff'),
    'image/png':     re.compile(r'^\x89PNG'),
    'video/mp4':     re.compile(r'^ftyp'),
    'video/mpeg':    re.compile(r'^\x00\x00\x01[BEG]'),
    'video/quicktime': re.compile(r'^\x00\x00\x00\x0f')
}


class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            self.type = None

            if self.type is None:
                mime = mimetypes.MimeTypes()
                guessed_type = mime.guess_type(
                    urllib.pathname2url(self.path)
                )[0]

                # some guessed types are too generic, filter them out
                if guessed_type is not None and len(guessed_type.split('/')) > 1:
                    self.type = guessed_type

            if self.type is None:
                with open(self.path, 'r') as f:
                    bytes = f.read(256)
                    for mime_type, magic in MAGIC.items():
                        if magic.match(bytes):
                            self.type = mime_type

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

